function Recommendation({ data, onBack, onClose, onStart }) {
  const { environment, recommendation } = data;
  const locationDescription =
    recommendation.location?.address ||
    recommendation.location?.description ||
    recommendation.location?.detail ||
    recommendation.location?.guideText ||
    "";

  return (
    <div className="recommendation-page">
      <div className="recommendation-header">
        <button
          className="recommendation-back"
          aria-label="뒤로가기"
          type="button"
          onClick={onBack}
        >
          <svg
            width="35"
            height="32"
            viewBox="0 0 35 32"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M21.875 24L13.125 16L21.875 8"
              stroke="#624001"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>

        <h1 className="recommendation-title">
          오늘의 {recommendation.durationMinutes}분
        </h1>

        <button
          className="recommendation-close"
          type="button"
          aria-label="닫기"
          onClick={onClose}
        >
          <svg
            width="30"
            height="29"
            viewBox="0 0 30 29"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M22.5 7.25L7.5 21.75M7.5 7.25L22.5 21.75"
              stroke="#624001"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
      </div>

      <div className="recommendation-content">
        <div className="recommendation-env-card">
          <div className="recommendation-env-item">
            <div className="recommendation-env-icon">
              <WeatherIcon weatherCondition={environment.weatherCondition} />
            </div>
            <p className="recommendation-env-text">
              {environment.temperature}° {toWeatherLabel(environment.weatherCondition)}
            </p>
          </div>

          <div className="recommendation-env-item">
            <p className="recommendation-env-text recommendation-env-pm">
              미세먼지 {toPmLabel(environment.pmGrade)}
            </p>
          </div>
        </div>

        <h2 className="recommendation-main-title">
          오늘의 식후 활동 추천
        </h2>

        <div className="recommendation-activity-card">
          <div className="recommendation-activity-icon-wrap">
            <div className="recommendation-activity-icon">
              <ActivityIcon activityType={recommendation.activityType} />
            </div>
          </div>

          <div className="recommendation-activity-text">
            <h3 className="recommendation-activity-name">
              공원 산책
            </h3>
            {(recommendation.guideText || recommendation.reason) && (
              <p className="recommendation-activity-desc">
                {recommendation.guideText || recommendation.reason}
              </p>
            )}
          </div>
        </div>

        {recommendation.location && (
          <div className="recommendation-location-section">
            <div className="recommendation-location-box">
              <h3 className="recommendation-location-title">
                추천 장소
              </h3>

              <h4 className="recommendation-location-name">
                {recommendation.location.name}
              </h4>

              <p className="recommendation-location-info">
                현재 위치에서 가까운 공원이에요.
              </p>

              <button
                type="button"
                className="recommendation-location-map"
                onClick={() => {
                  const { latitude, longitude } = recommendation.location;

                  window.open(
                    `https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`,
                    "_blank"
                  );
                }}
              >
                지도에서 보기 <span>›</span>
              </button>
            </div>
          </div>
        )}
      </div>   
    </div>
  );
}

export default Recommendation;